<?php $total=0;foreach($products as $p){$price=(float)$p['sale_price']>0?$p['sale_price']:$p['price'];$total+=$price*$_SESSION['cart'][$p['id']];}?><div class="checkout-steps"><span class="done">1 Carrito</span><span class="active">2 Entrega</span><span>3 Pago</span><span>4 Confirmación</span></div><div class="row g-4"><div class="col-lg-8"><div class="card p-4"><h2 class="section">Datos de entrega</h2><form method="post" action="/?r=checkoutSave"><input type="hidden" name="csrf" value="<?=csrf()?>"><div class="row g-3"><div class="col-md-6"><label>Nombre completo</label><input class="form-control" name="fullname" value="<?=e(auth()['name'])?>" required></div><div class="col-md-6"><label>Correo electrónico</label><input class="form-control" type="email" name="email" value="<?=e(auth()['email'])?>" required></div><div class="col-12"><label>Dirección de entrega</label><input class="form-control" name="address" minlength="8" placeholder="Zona, colonia, calle, número..." required></div><div class="col-md-6"><label>Método de entrega</label><select class="form-select" name="shipping_method"><option value="DOMICILIO">Entrega a domicilio</option><option value="RETIRO">Retiro en punto de entrega (demo)</option></select></div><div class="col-12"><label>Indicaciones adicionales</label><textarea class="form-control" name="notes" placeholder="Referencia o instrucciones para la entrega"></textarea></div></div><button class="btn grad mt-4 px-4">Continuar al pago</button></form></div></div><div class="col-lg-4"><div class="card p-4 summary"><h4>Tu pedido</h4><?php foreach($products as $p):?><div class="sumrow"><span><?=e($p['name'])?> × <?=$_SESSION['cart'][$p['id']]?></span></div><?php endforeach;?><hr><div class="sumrow total"><span>Total</span><b>Q<?=number_format($total,2)?></b></div></div></div></div>